window.DOSIK=window.DOSIK||{};DOSIK["sm_admin"]={"1":[{"t":"tree","title":"행정소송의 종류","root":"행정소송(제3조)","branches":[["항고소송","행정청의 처분등이나 부작위에 대하여 제기 · 취소소송, 무효등 확인소송, 부작위위법확인소송으로 나뉜다(제4조) · 처분등에는 행정심판에 대한 재결이 포함된다(제2조)"],["부작위위법확인소송","부작위만 대상으로 하고 거부처분은 취소소송이나 무효확인소송으로 다툰다"],["당사자소송"],["민중소송"],["기관소송","국가 또는 공공단체의 기관 상호간 권한의 존부·행사에 관한 다툼을 대상으로 하며 헌법재판소 관장사항인 권한쟁의는 빠진다"]]},{"t":"tree","title":"허용되지 않는 소송","root":"판례가 허용하지 않는 소송","branches":[["의무이행소송"],["예방적 부작위청구소송","준공처분을 하지 말라는 소송 등"],["작위의무확인소송"],["거부처분에 대한 가처분"],["적극적 변경","취소소송에서 일부취소는 되지만 처분을 다른 내용으로 바꾸라는 적극적 변경은 구할 수 없다"],["압수물 환부이행청구소송","검사에 대한 소송"]]},{"t":"vs","title":"사법심사의 한계","cols":[{"name":"다툴 수 없는 것","items":["단순한 사실관계의 존부","반사적 이익의 침해","부당에 그치는 재량 행사","검사의 불기소처분과 공소제기는 형사절차로 다툰다","국회의원 징계","공정거래위원회의 고발조치","군의관의 병역법상 신체등위판정","객관소송인 민중소송·기관소송은 법률이 정한 경우에 법률에 정한 자만 제기한다(제45조)"]},{"name":"다툴 수 있는 것","items":["재량처분이라도 재량권의 한계를 넘거나 남용이 있으면 법원이 취소할 수 있다(제27조)","지방의회 의원 징계는 처분으로서 항고소송으로 다툰다","조례나 고시라도 집행행위 없이 그 자체로 직접 국민의 구체적 권리의무를 규율하면 처분이 되어 취소소송·무효확인소송의 대상이 된다"]}]},{"t":"table","title":"소송의 준용과 요건","head":["주제","내용"],"rows":[["명령·규칙 위반 확정","대법원판결로 명령·규칙이 헌법 또는 법률에 위반된다고 확정되면 대법원은 지체 없이 행정안전부장관에게 통보하고 장관은 관보에 게재한다(제6조)"],["준용 법률","행정소송법에 특별한 규정이 없는 사항은 법원조직법과 민사소송법 및 민사집행법을 준용한다(제8조 제2항) · 행정심판법은 준용되지 않는다"],["선결문제","처분의 효력 유무가 민사소송의 선결문제이면 수소법원에 행정청의 소송참가, 행정심판기록 제출명령, 직권심리, 소송비용 재판의 효력 규정이 준용되고 재판관할·사정판결은 준용되지 않는다(제11조)"],["소송요건","대상적격, 원고적격, 피고적격, 소의 이익, 제소기간, 필요한 경우 행정심판전치는 법원의 직권조사사항이다 · 요건이 빠지면 처분이 위법해도 각하판결을 하고, 원고는 요건을 보완해 다시 소를 낼 수 있다 · 처분의 위법성은 소송요건이 아니라 본안 판단 사항이다"],["당사자소송","공법상 신분·지위 확인소송, 공법상 계약에 따른 의무 이행청구는 허용된다 · 국가 상대 당사자소송의 가집행선고를 막던 제43조는 헌법재판소 위헌결정으로 효력을 잃고 2026.5.12 삭제되어 지금은 가집행선고를 할 수 있다 · 피고적격, 제소기간, 제3자 재심청구 규정은 준용되지 않는다"]]}],"2":[{"t":"def","term":"처분","text":"행정청이 구체적 사실에 관하여 하는 법집행으로서 공권력의 행사 또는 그 거부와 이에 준하는 행정작용(제2조) · 국민의 권리의무에 직접 영향을 주는지가 기준이어서 행정규칙에 근거한 행위라도 권리의무를 직접 바꾸면 처분 · 조례·고시도 집행행위 없이 직접 권리의무를 규율하면 처분"},{"t":"vs","title":"처분의 예","cols":[{"name":"처분으로 인정된 예","items":["세무조사결정, 소득금액변동통지, 결손금 감액경정 통지","개별공시지가결정, 부담(부관)","건축신고 반려, 지목변경신청 반려, 토지대장 직권말소","국가인권위원회 성희롱결정·시정조치권고, 금융감독원장의 문책경고","지방의회 의장선임의결, 이행강제금 최초 독촉","폐기물처리 사업계획 부적정통보, 지방의료원 폐업결정","재임용을 거부하는 취지의 임용기간만료 통지"]},{"name":"처분이 아닌 예","items":["도시기본계획, 4대강 마스터플랜, 혁신도시 최종입지선정","공정거래위원회 고발조치, 공매통지, 국세환급금결정","운전면허 벌점 배점, 당연퇴직 인사발령, 군의관 신체등위판정","입국금지결정(외부에 통지되지 않은 내부 결정), 금융감독위원회의 파산신청","반복된 제2차 계고와 반복된 독촉은 새 의무를 부과하지 않음","과태료 부과는 질서위반행위규제법 절차로 다툰다"]}]},{"t":"tree","title":"거부처분과 신청권","root":"거부처분","branches":[["요건","거부가 처분이 되려면 신청한 행위가 공권력 행사이고 거부가 신청인의 법률관계에 영향을 주며 신청인에게 법규상 또는 조리상 신청권이 있어야 한다"],["신청권","관계 법규의 해석으로 추상적으로 정하고, 인용될 수 있는지는 본안에서 판단한다 · 응답을 받을 권리이지 인용을 받을 권리가 아니다"],["조리상 신청권 인정","주민등록번호가 본인 의사와 무관하게 유출된 사람의 변경신청, 도시계획구역 내 토지소유자의 도시계획 입안·변경신청, 공사중지명령 원인 소멸 후 철회신청"],["거부해도 처분 아님","경정청구기간이 지난 뒤의 경정청구, 불가쟁력이 생긴 처분의 변경신청, 토지대장 소유자명의변경신청 · 직권취소를 할 수 있다는 사정만으로 이해관계인에게 취소 신청권이 생기지 않는다"]]},{"t":"table","title":"소송 대상","head":["주제","내용"],"rows":[["증액경정처분","당초 처분은 증액경정처분에 흡수되어 증액경정처분이 소송 대상이다"],["감액경정처분","당초 처분 중 감액되지 않고 남은 부분이 대상이다 · 제재처분을 유리하게 바꾼 변경처분도 변경된 내용의 당초 처분이 대상이다"],["원처분주의","취소소송은 처분등을 대상으로 하고 재결취소소송은 재결 자체에 고유한 위법이 있을 때만 허용된다(제19조) · 재결을 거쳐도 원칙적으로 원처분을 다투고, 변경재결이 있으면 변경된 원처분을 대상으로 원처분청을 피고로 한다 · 고유한 위법이 없는데 재결을 다투면 각하가 아니라 기각판결을 한다"],["재결 고유의 위법","주체·절차·형식뿐 아니라 내용상 위법도 포함된다 · 적법한 심판청구를 각하한 재결, 심판 대상이 아닌 관념의 통지에 대한 인용재결이 그 예이다 · 제3자의 심판청구로 인용재결이 나와 비로소 권리를 침해받은 처분 상대방은 인용재결의 취소를 구할 수 있고 피고는 행정심판위원회이다"],["재결주의","감사원 변상판정에 대한 재심의판정, 중앙노동위원회 재심판정, 특허심판원 심결은 재결을 대상으로 소를 낸다"],["원처분주의 적용","교원소청심사위원회 결정, 국가공무원법상 소청결정, 국세기본법상 심판결정, 토지수용 이의재결 · 사립학교 교원 징계는 학교법인의 사법상 행위여서 소청심사위원회 결정이 처분으로서 소송 대상이 된다"]]}],"3":[{"t":"def","term":"법률상 이익","text":"처분의 근거 법규와 관련 법규가 보호하는 개별적·직접적·구체적 이익 · 사실적·경제적 이해관계나 명예 같은 인격적 이익만으로는 부족하고 이는 무효등 확인소송도 같다","ex":["취소소송은 처분등의 취소를 구할 법률상 이익이 있는 자가 제기한다(제12조)"]},{"t":"tree","title":"원고적격","root":"원고적격","branches":[["존속과 조사","직권조사사항이고 사실심 변론종결시는 물론 상고심에서도 존속해야 한다 · 상고심에서 흠결되면 소는 부적법해진다"],["위명","처분 상대방이 위명을 사용했어도 처분의 효과가 그에게 미치므로 원고적격이 있다"],["경업자","기존 담배 일반소매인, 노선이 겹치는 기존 버스·화물운송사업자, 영업지역 내 이전을 다투는 기존 약종상은 신규 업자에 대한 수익적 처분을 다툴 원고적격이 있다"],["경업자 부정","기존 일반소매인이 신규 구내소매인 지정을 다투는 경우와 경업자에게 불리한 처분을 다투는 경우는 원고적격이 없다"],["경원자","경원관계에서 불선정된 사업자는 자신에 대한 불선정처분의 취소를 구할 수 있다"]]},{"t":"vs","title":"원고적격의 유무","cols":[{"name":"원고적격 있음","items":["환경영향평가 대상지역 안의 주민, 원자로시설부지 인근 주민, 오염 우려 취수장에서 물을 받는 주민은 환경상 이익 침해가 사실상 추정된다","대학교 총학생회는 임시이사선임처분을 다툴 수 있다","지방자치단체는 다른 지방자치단체장의 건축협의 취소를 다툴 수 있다"]},{"name":"원고적격 없음","items":["생태·자연도 등급 변경을 다투는 인근 주민과 환경상 이익을 주장하는 재단법인 수녀원","대학 직원 노동조합, 대한의사협회(상대가치점수 고시), 한약조제시험 합격처분을 다투는 한의사","국가는 기관위임사무를 처리한 지방자치단체장을 상대로 취소소송을 낼 수 없다"]}]},{"t":"vs","title":"소의 이익","cols":[{"name":"소의 이익 있음","items":["처분의 효과가 기간 경과·집행 등으로 소멸한 뒤에도 취소로 회복되는 법률상 이익이 있으면 소를 낼 수 있다(제12조 제2문)","가중 제재 규정이 있는 의사면허자격정지는 정지기간이 지나도 소의 이익이 있다","해임·파면 후 임기만료나 당연퇴직이 생겨도 그 사이 보수를 청구할 수 있으면 소의 이익이 있다","사업양도가 무효라고 주장하는 양도인은 지위승계신고 수리처분을 다툴 수 있다","공장설립승인이 쟁송취소되어도 공장건축허가가 남아 있으면 인근 주민은 건축허가 취소를 구할 이익이 있다","지방의회 의원 제명 후 임기만료, 입학시기가 지난 불합격처분, 감봉 후 자진퇴직한 공무원의 감봉처분"]},{"name":"소의 이익 없음","items":["건축공사가 완료된 뒤 이웃주민의 건축허가 취소청구, 인접주택 소유자의 사용승인 취소청구","새 시험에 합격한 뒤 이전 불합격처분 취소청구, 대집행 완료 후 계고처분 취소청구","새 사유로 직위해제를 다시 하면 이전 직위해제는 효력을 잃어 다툴 이익이 없고 소송 중 처분이 직권취소된 경우도 같다","재결에 따른 후속처분이 아니라 거부처분을 취소한 재결 자체를 다투는 것","증액·감액 항목을 함께 경정한 결과 전체 소득처분금액이 줄었다면 소득금액변동통지 취소를 구할 이익이 없다","압류 후 압류부동산을 매수한 자는 압류처분 취소를 구할 원고적격이 없다"]}]}],"4":[{"t":"table","title":"재판관할","head":["주제","내용"],"rows":[["제1심 관할","취소소송의 제1심 관할법원은 피고의 소재지를 관할하는 행정법원이다(제9조 제1항)"],["대법원소재지","중앙행정기관과 그 부속기관, 합의제행정기관 또는 그 장, 국가 사무를 위임·위탁받은 공공단체 또는 그 장이 피고이면 대법원소재지를 관할하는 행정법원에도 낼 수 있다 · 토지수용 등 부동산이나 특정 장소에 관계되는 처분은 그 소재지 행정법원에도 낼 수 있고 토지관할은 전속관할이 아니다"],["2026 개정 해사행정사건","2026.3.17 신설된 제9조 제4항에 따라 법원조직법상 해사행정사건에 해당하는 취소소송은 피고 소재지를 관할하는 해사국제상사법원에 전속한다 · 해사행정사건 취소소송과 관련청구소송의 이송·병합은 해사국제상사법원에만 할 수 있다(제10조 제3항) · 특허심판원 심결취소소송은 특허법원 전속관할이다"],["잘못 제기한 소의 이송","원고의 고의 또는 중대한 과실 없이 심급을 달리하는 법원에 잘못 제기하거나 행정소송을 민사소송으로 잘못 제기하면 각하하지 않고 관할법원에 이송한다(제7조) · 수소법원이 항고소송 관할도 가지고 있으면 행정소송으로 심리해야 한다 · 민사사건을 당사자소송으로 행정법원에 냈는데 피고가 항변 없이 본안 변론을 하면 변론관할이 생긴다"]]},{"t":"tree","title":"피고적격","root":"피고(제13조)","branches":[["원칙","피고는 처분을 한 행정청이고 처분 후 권한이 승계되면 승계한 행정청, 행정청이 없어지면 사무가 귀속되는 국가 또는 공공단체가 피고이다"],["내부위임","내부위임을 받은 기관이 자기 이름으로 처분하면 그 기관이, 대리관계를 밝혀 처분하면 피대리청이 피고이다 · 처분청과 통지한 자가 다르면 처분청이 피고이다"],["판례","조례는 공포한 지방자치단체장이, 교육조례는 교육감이 피고이고 지방의회는 피고가 아니다 · 지방의회 의장선임의결은 지방의회가 피고이다"],["합의제 행정청","그 자체가 피고이지만 중앙노동위원회 처분은 노동위원회법에 따라 위원장이 피고이다 · 권한을 위탁받은 사인, 지방법무사회, 국회의 기관도 처분을 하면 피고가 된다"]]},{"t":"table","title":"피고경정과 소송참가","head":["주제","내용"],"rows":[["피고경정","원고가 피고를 잘못 지정하면 법원은 원고의 신청으로 결정하여 피고경정을 허가하고 직권으로는 하지 못한다(제14조) · 사실심 변론종결시까지 할 수 있고 새 피고에 대한 소는 처음 소를 제기한 때에 제기된 것으로, 종전 피고에 대한 소는 취하된 것으로 본다 · 신청 각하결정에는 즉시항고할 수 있고 권한 승계·행정청 소멸로 인한 경정은 직권으로도 한다"],["소송참가","법원은 소송 결과로 권리 또는 이익을 침해받을 제3자를 당사자·제3자의 신청 또는 직권으로 참가시킬 수 있고 미리 당사자와 제3자의 의견을 듣는다(제16조) · 참가 이익은 법률상 이익이어야 하고 참가인은 공동소송적 보조참가인의 지위를 가진다 · 다른 행정청의 참가도 신청 또는 직권으로 하며 행정청은 민사소송법상 보조참가를 할 수 없지만 제3자는 요건을 갖추면 보조참가도 할 수 있다"]]},{"t":"table","title":"이송·병합과 소의 변경","head":["주제","내용"],"rows":[["관련청구소송","당해 처분과 관련되는 손해배상·부당이득반환·원상회복 청구와 관련 취소소송이 관련청구소송이다(제10조)"],["이송","관련청구소송이 계속된 법원이 상당하다고 인정할 때 신청 또는 직권으로 취소소송이 계속된 법원으로 한다"],["병합","사실심 변론종결시까지 피고 외의 자를 상대로도 할 수 있고 본래의 취소소송이 각하되면 병합된 관련청구도 각하된다"],["소의 종류 변경","취소소송은 청구의 기초에 변경이 없는 한 사실심 변론종결시까지 원고의 신청으로 당사자소송이나 다른 항고소송으로 변경할 수 있고 허가결정에는 즉시항고할 수 있다(제21조) · 변경된 소는 처음 소를 제기한 때에 제기된 것으로 본다"],["처분변경","소 제기 후 처분이 변경되면 처분 변경을 안 날부터 60일 이내에 신청해야 한다(제22조)"]]}],"5":[{"t":"table","title":"제소기간","head":["주제","내용"],"rows":[["90일과 1년","취소소송은 처분등이 있음을 안 날부터 90일 이내, 처분등이 있은 날부터 1년 이내에 제기해야 하고 둘 중 하나라도 지나면 제기하지 못한다(제20조) · 90일은 불변기간이어서 법원이 늘이거나 줄일 수 없고 1년은 정당한 사유가 있으면 예외가 인정된다 · 제소기간 준수 여부는 직권조사사항이다"],["안 날·있은 날","안 날은 유효한 처분이 있음을 현실적으로 안 날이고 있은 날은 처분의 효력이 발생한 날이다 · 처분서가 주소지에 송달되면 반증이 없는 한 알았다고 추정할 뿐 간주하지는 않는다 · 고시로 불특정다수에게 한 처분은 고시의 효력발생일에 알았다고 보고 특정인에 대한 처분을 주소불명으로 공고한 경우는 상대방이 현실적으로 안 날이 기준이다"],["행정심판을 거친 경우","행정심판청구를 한 경우에는 재결서 정본을 송달받은 날부터 90일, 재결이 있은 날부터 1년이 제소기간이다 · 발송일이나 심판청구일이 아니다 · 청구기간을 넘겨 각하된 재결 뒤에는 재결서 송달일이 아니라 원처분을 안 날이 기준이어서 그 뒤에 낸 소는 기간을 지킨 것이 아니다"],["기간 계산 특례","국외에서의 소송행위추완은 14일을 30일로, 제3자 재심청구는 30일을 60일로, 소의 제기는 60일을 90일로 한다(제5조) · 기간의 말일이 공휴일이면 다음 날 만료한다 · 재조사결정에 따른 소송의 제소기간은 후속 처분의 통지를 받은 날부터 기산한다"]]},{"t":"flow","title":"행정기본법상 이의신청","steps":["처분에 이의가 있는 당사자는 처분을 받은 날부터 30일 이내에 해당 행정청에 이의신청(행정기본법 제36조)","행정청은 14일 이내에 결과를 통지","결과를 통지받은 날(기간 내 통지가 없으면 통지기간 만료 다음 날)부터 90일 이내에 행정심판이나 행정소송을 제기 · 이의신청과 관계없이 바로 소송을 낼 수도 있다"]},{"t":"table","title":"제소기간의 범위","head":["주제","내용"],"rows":[["소송별 적용","무효확인소송에는 제소기간이 없지만 무효선언을 구하는 취소소송은 제소기간과 전치요건을 갖추어야 한다 · 부작위위법확인소송은 행정심판을 거쳤다면 재결서 정본 송달일부터 90일의 제한을 받는다 · 당사자소송에는 제20조가 준용되지 않고 법령에 기간이 있으면 그 기간이 불변기간이다(제41조)"],["소 변경","소의 종류 변경이나 이송 후 취소소송으로 바꾼 경우에는 처음 소를 제기한 때를 기준으로 한다 · 청구취지를 교환적으로 변경하거나 추가한 경우는 원칙적으로 변경·추가 신청이 있은 때가 기준이다 · 무효확인의 소가 취소소송 제소기간 안에 제기되었다면 나중에 추가 병합한 취소청구도 적법하다"]]},{"t":"vs","title":"행정심판 전치","cols":[{"name":"임의적 전치(원칙)","items":["행정심판은 원칙적으로 거치지 않고도 취소소송을 낼 수 있다(제18조)","행정소송법에는 제소기간 불고지·오고지 규정이 없어 행정청이 긴 기간을 알려도 법정 기간이 지나면 부적법하다"]},{"name":"필요적 전치(예외)","items":["다른 법률에 재결을 거치도록 한 경우","국세(심사·심판청구), 지방세(조세심판원 심판청구 또는 감사원 심사청구), 국가공무원 징계(소청), 운전면허 처분","재결 없이 소를 낼 수 있는 경우: 청구 후 60일이 지나도 재결이 없을 때, 중대한 손해를 막을 긴급한 필요가 있을 때 등","심판청구 자체 없이 소를 낼 수 있는 경우: 동종사건에 이미 기각재결이 있을 때, 관련 처분 하나가 재결을 거쳤을 때, 행정청이 거칠 필요가 없다고 잘못 알린 때 등이며 그 사유는 원고가 소명한다","전치 요건은 사실심 변론종결시까지 갖추면 되고 전심에서 하지 않은 주장도 소송에서 할 수 있다"]}]}],"6":[{"t":"flow","title":"집행정지","steps":["취소소송을 제기해도 처분등의 효력이나 집행, 절차의 속행은 멈추지 않는다(집행부정지 원칙, 제23조 제1항)","예외로 법원이 집행정지를 결정","처분의 효력정지는 집행이나 절차 속행 정지로 목적을 이룰 수 있으면 허용되지 않고 처분 효력의 일부만 정지할 수도 있다"]},{"t":"table","title":"집행정지의 요건","head":["요건","내용"],"rows":[["적극적 요건","본안이 계속 중이고 처분등의 존재, 회복하기 어려운 손해, 이를 예방할 긴급한 필요가 있어야 한다 · 회복하기 어려운 손해에는 금전으로 보상할 수 없는 손해와 무형의 손해도 들어간다 · 중대한 손해는 행정심판법상 집행정지 요건이다"],["본안 계속과 관할","소 제기 전에는 집행정지를 할 수 없고 본안이 계속된 법원이 관할하므로 본안이 상급심에 있으면 그 법원이 결정한다 · 본안소송은 소송요건을 갖춘 적법한 것이어야 하고 본안이 계속 중이라는 점은 신청인이 주장·소명한다"],["소극적 요건","공공복리에 중대한 영향을 미칠 우려가 있으면 허용되지 않고(제23조 제3항) 이 점은 행정청이 소명한다 · 판례는 본안청구가 이유 없음이 명백하지 않을 것도 요건으로 본다 · 회복하기 어려운 손해와 신청 이유는 신청인이 소명해야 한다"]]},{"t":"table","title":"집행정지의 절차와 효력","head":["주제","내용"],"rows":[["절차와 불복","집행정지는 당사자의 신청 또는 법원의 직권으로 결정한다 · 요건을 갖추지 못한 부적법한 신청은 각하한다 · 집행정지결정과 기각결정 모두 즉시항고할 수 있지만 집행정지결정에 대한 즉시항고에는 집행을 정지하는 효력이 없다(제23조 제5항)"],["효력과 종기","집행정지결정은 제3자에게도 효력이 있고 당사자인 행정청과 관계행정청을 기속한다(제29조 제2항, 제23조 제6항) · 효력은 장래를 향해서만 생기고 기간이 끝나거나 본안이 확정되어도 소급해 소멸하지 않는다 · 행정소송규칙 제10조는 종기를 본안판결 선고일부터 30일 이내의 범위에서 정하도록 한다"],["효력 소멸","본안소송이 취하되면 별도 결정 없이 집행정지의 효력이 소멸하고 본안판결 선고로도 소멸한다 · 처분이 적법하다고 확정되어 정지가 끝나면 처분의 효력이 되살아나 정지기간 중 교부된 보조금의 반환을 명할 수 있다 · 과징금 납부기한은 정지기간 동안 진행하지 않는다"],["집행정지 취소","집행정지결정이 확정된 뒤에도 공공복리에 중대한 영향을 미치거나 정지사유가 없어지면 당사자의 신청 또는 직권으로 결정을 취소할 수 있다(제24조) · 취소결정과 그 불복에는 집행정지의 소명·즉시항고 규정이 준용된다"]]},{"t":"vs","title":"집행정지의 적용 범위","cols":[{"name":"인정","items":["취소소송과 무효등 확인소송(처분부존재확인 포함)에 인정된다"]},{"name":"인정되지 않음","items":["부작위위법확인소송과 당사자소송에는 준용되지 않는다","거부처분은 정지해도 신청 전 상태로 돌아갈 뿐이어서 집행정지 대상이 아니다","행정처분의 금지를 구하는 민사집행법상 가처분은 허용되지 않는다"]}]}],"7":[{"t":"table","title":"심리의 구조","head":["주제","내용"],"rows":[["기본 구조","행정소송은 변론주의를 기본 구조로 하고 직권심리가 보충적으로 더해진다 · 법원은 필요하면 직권으로 증거조사를 하고 당사자가 주장하지 않은 사실도 판단할 수 있지만(제26조) 기록상 나타난 사항에 한한다 · 공개심리, 쌍방심리, 구술심리, 자유심증주의, 직권진행주의도 적용된다"],["처분권주의와 석명권","불고불리 원칙이 적용되어 법원은 원고의 청구범위를 넘어 인용하거나 청구하지 않은 처분을 취소할 수 없다 · 석명권은 진술의 모순·불명확을 보완하게 하거나 입증을 촉구하는 범위에서 행사한다 · 새로운 청구나 주장하지 않은 요건사실·공격방어방법을 권유하면 석명권의 한계를 넘는다"]]},{"t":"vs","title":"직권조사사항과 본안","cols":[{"name":"직권조사사항","items":["제소기간, 원고적격, 대상적격, 소의 이익, 전심절차 준수 같은 소송요건"]},{"name":"본안 판단사항","items":["처분청의 권한 유무, 행정절차법상 처분절차 준수, 재량남용 여부","직권조사사항이 아닌 위법사유는 취소를 구하는 원고가 구체적 사실을 먼저 주장해야 한다"]}]},{"t":"vs","title":"증명책임","cols":[{"name":"피고 행정청","items":["취소소송에서 처분의 적법성은 원칙적으로 피고 행정청이 증명한다","허가기준 미달 불허가처분, 과세소득과 그 귀속 사업연도, 정보공개 비공개사유도 피고가 증명한다"]},{"name":"원고","items":["재량권 일탈·남용, 비과세·면제 사유, 무효확인소송의 무효 사유는 원고가 증명한다","증명은 고도의 개연성으로 족하다"]}]},{"t":"table","title":"위법판단 기준시","head":["주제","내용"],"rows":[["위법판단 기준시","항고소송에서 처분의 위법 여부는 처분 당시의 법령과 사실상태를 기준으로 하고 처분 후 법령 개폐나 사실 변동에 영향을 받지 않는다 · 거부처분 취소소송과 계속효 있는 처분도 처분시가 기준이다 · 부작위위법확인소송은 처분이 없으므로 재결을 거쳤는지와 관계없이 사실심 변론종결시가 기준이다"],["판단 자료와 적용 법령","기준시는 처분시이지만 법원은 사실심 변론종결시까지 제출된 모든 자료로 처분 당시의 객관적 사실을 확정한다 · 허가신청 후 기준이 바뀌면 바뀐 기준에 따라 처분하는 것이 원칙이고 행정청이 정당한 이유 없이 처리를 늦춘 경우만 예외이다 · 제재처분은 처분시 시행령이 불리하게 바뀌었으면 행위시 시행령을 적용한다"],["처분사유의 추가·변경","행정소송법에는 규정이 없고 판례와 행정소송규칙 제9조가 사실심 변론종결시까지 당초 처분사유와 기본적 사실관계가 동일한 범위에서 허용한다 · 동일성은 법적 평가가 아니라 사회적 사실관계를 기준으로 하며 처분시에 존재하던 사유만 추가할 수 있다 · 제한 취지는 상대방의 방어권 보장과 신뢰보호이다"],["추가·변경 허용 판례","사실관계가 같으면 근거법령만 바꾸거나 추가할 수 있고 불명확한 당초 사유를 구체적으로 설명하는 것은 새 사유가 아니다 · 산림형질변경 불허가에서 준농림지역 행위제한과 중대한 공익상 필요는 동일성이 있다 · 계약 불이행과 공무원에 대한 뇌물 제공, 무자료주류판매와 무면허업자에 대한 판매는 동일성이 없다"],["조세소송·행정심판기록","조세소송의 소송물은 과세단위별 개개의 부과처분이고 과세관청은 사실심 변론종결시까지 세액의 정당성을 뒷받침할 새 자료를 낼 수 있다 · 법원은 제출 자료로 정당한 세액을 직권으로 산출할 수 있다 · 행정심판기록 제출명령은 당사자의 신청이 있을 때 재결청에 결정으로 하며(제25조) 당사자소송에도 준용된다"]]}],"8":[{"t":"tree","title":"일부취소","root":"일부취소","branches":[["요건","처분이 가분이고 취소할 부분을 특정할 수 있을 때만 하므로 세대별로 나뉘는 분양전환승인, 분리되는 공개 가능 정보, 상이별 국가유공자 비해당결정은 그 부분만 취소한다"],["기속행위","과세처분·개발부담금처럼 기속행위인 금전부과는 정당한 금액을 산출할 수 있으면 초과 부분만, 산출할 수 없으면 전부 취소한다"],["재량행위","영업정지·과징금은 법원이 적정한 정도를 정할 수 없어 법정 한도를 넘은 경우라도 전부 취소한다"]]},{"t":"table","title":"판결의 효력","head":["효력","내용"],"rows":[["형성력과 제3자효","처분을 취소하는 확정판결로 처분은 처분시에 소급해 소멸한다 · 취소판결은 제3자에게도 효력이 있고(제29조) 집행정지결정과 그 취소결정, 무효확인판결, 부작위위법확인판결에도 준용되지만 당사자소송과 기각판결에는 제3자효가 없다 · 취소판결만으로 처분을 기초로 새로 형성된 제3자의 권리가 당연히 원상회복되지는 않는다"],["기속력의 범위","처분을 취소하는 확정판결은 당사자인 행정청과 그 밖의 관계행정청을 기속하고(제30조 제1항) 원고에게는 미치지 않는다 · 인용판결에만 생기고 각하·기각판결과 사정판결에는 없으며 무효확인판결과 당사자소송 판결에는 준용된다 · 주문뿐 아니라 이유 중 구체적 위법사유의 판단에도 미치고 행정청은 위법한 결과를 제거할 의무를 진다"],["반복금지와 재처분의무","거부처분이 취소되면 행정청은 판결 취지에 따라 이전 신청에 대해 다시 처분해야 하고 신청에 따른 처분이 절차 위법으로 취소된 때도 같다(제30조 제2항·제3항) · 기속력은 종전 처분 당시까지의 사유에만 미쳐 처분 후의 새 사유나 개정 법령, 기본적 사실관계가 다른 사유로 다시 거부할 수 있다 · 절차 위법으로 취소되면 적법한 절차를 거쳐 같은 내용의 처분을 할 수 있다"]]},{"t":"tree","title":"간접강제","root":"간접강제","branches":[["기속력 위반","기속력에 반하는 처분은 하자가 중대·명백하여 당연무효이고 취소판결 확정 후 그 처분을 경정한 처분도 무효이다"],["요건","행정청이 재처분을 하지 않거나 기속력에 반하는 재처분을 하면 당사자의 신청으로 제1심수소법원이 결정하여 지연배상이나 즉시 손해배상을 명한다(제34조)"],["적용 범위","거부처분취소판결과 부작위위법확인판결에만 인정되고 무효확인판결·당사자소송에는 없으며 법원의 직접처분 제도는 없다"],["배상금의 성질","배상금은 제재나 손해배상이 아니라 재처분을 하게 하는 심리적 강제수단이다 · 이행기간이 지난 뒤라도 재처분을 하면 더 이상 추심할 수 없다 · 결정은 변론 없이 할 수 있고 민사집행법 제262조(채무자 심문)가 준용되며 효력은 행정청이 속한 국가 또는 공공단체에 미친다"]]},{"t":"table","title":"기판력·사정판결·재심","head":["주제","내용"],"rows":[["기판력","행정소송법에 기판력 규정은 없고 민사소송법이 준용된다 · 사실심 변론종결시를 기준으로 주문에 포함된 처분의 위법성 존부 판단에만 생기고 처분이 귀속하는 국가·공공단체에도 미친다 · 과세처분 취소청구 기각판결의 기판력은 같은 처분의 무효확인소송에도 미치지만 취소판결이 곧바로 국가배상의 고의·과실까지 인정하지는 않는다"],["사정판결","청구가 이유 있어도 처분을 취소하는 것이 현저히 공공복리에 적합하지 않으면 기각할 수 있고 주문에 처분이 위법함을 명시한다(제28조) · 위법성은 처분시, 공공복리 적합성은 사실심 변론종결시가 기준이고 신청 없이 직권으로도 하며 극히 엄격하게 적용한다 · 무효확인·부작위위법확인소송에는 준용되지 않고 원고는 손해배상 등을 병합할 수 있으며 소송비용은 피고가 부담한다"],["제3자 재심","취소판결로 권리를 침해받은 제3자가 자기에게 책임 없는 사유로 소송에 참가하지 못해 공격방어방법을 내지 못했으면 확정판결을 안 날부터 30일, 확정된 날부터 1년 이내에 재심을 청구할 수 있고 이는 불변기간이다(제31조) · 무효확인·부작위위법확인소송에 준용되고 당사자소송에는 준용되지 않는다"],["소송비용","사정판결이나 행정청의 처분 취소·변경으로 각하·기각된 경우 소송비용은 피고가 부담한다(제32조)"]]}],"9":[{"t":"tree","title":"무효등 확인소송","root":"무효등 확인소송","branches":[["종류","처분등의 효력 유무 또는 존재 여부를 확인하는 소송으로 무효확인, 유효확인, 실효확인, 존재확인, 부존재확인이 포함되고 재결의 무효확인도 된다 · 처분의 존재 여부도 심리 대상이다"],["허용되지 않는 소송","작위의무확인소송은 허용되지 않는다"],["원고적격","처분등의 효력 유무 등의 확인을 구할 법률상 이익이 있는 자가 제기하고 처분 상대방이 아닌 제3자도 법률상 이익이 있으면 된다(제35조)"],["보충성","대법원 전원합의체 판결(2007두6342)은 민사소송의 확인의 이익, 즉 보충성이나 즉시확정의 이익을 요구하지 않는다 · 이행소송 같은 직접적 구제수단이 있어도 무효확인을 구할 수 있다"]]},{"t":"table","title":"소송요건 특례와 취소청구","head":["주제","내용"],"rows":[["소송요건 특례","무효등 확인소송에는 제소기간(제20조)과 행정심판 전치(제18조)가 준용되지 않아 행정심판을 거쳤더라도 기간 제한이 없다 · 무효를 선언하는 의미의 취소소송은 취소소송이므로 제소기간과 전치요건을 갖추어야 한다 · 무효 사유의 증명책임은 원고에게 있다"],["취소청구와의 관계","무효확인청구에는 특별한 사정이 없는 한 취소를 구하는 취지도 포함되어 있어 무효사유가 증명되지 않아도 취소소송 요건을 갖추었으면 취소사유를 심리해야 한다 · 두 청구는 양립할 수 없어 주위적·예비적 병합만 되고 단순·선택적 병합은 안 된다 · 가분인 처분은 일부만 무효확인할 수 있다"],["준용 규정","재판관할, 관련청구 이송·병합, 피고적격, 공동소송, 제3자·행정청 소송참가, 처분변경으로 인한 소의 변경, 집행정지, 제3자효, 기속력, 제3자 재심이 준용된다(제38조 제1항) · 제소기간, 전치, 사정판결, 간접강제는 준용되지 않아 거부처분 무효확인판결에는 재처분의무만 있고 간접강제는 없다 · 취소소송·당사자소송으로 소를 변경할 수 있다(제37조)"]]},{"t":"tree","title":"부작위위법확인소송","root":"부작위위법확인소송","branches":[["부작위","행정청이 당사자의 신청에 대하여 상당한 기간 내에 일정한 처분을 할 법률상 의무가 있는데도 하지 않는 것이다(제2조) · 신청인에게 법규상 또는 조리상 신청권이 있어야 하고 그 존부는 소송요건 단계에서 판단하지만 신청 내용이 적법할 필요는 없다"],["대상이 아닌 것","거부처분, 입법부작위, 검사의 압수물 환부 부작위는 이 소송의 대상이 아니다"],["원고적격","처분의 신청을 한 자로서 부작위 위법 확인을 구할 법률상 이익이 있는 자만 제기한다(제36조)"],["소의 이익","소 제기 전후를 통해 판결시까지 행정청이 인용이든 거부든 처분을 하면 부작위가 해소되어 소는 각하된다 · 이때 행정소송규칙 제17조에 따라 소송비용의 전부 또는 일부를 피고에게 부담시킬 수 있다"]]},{"t":"table","title":"부작위위법확인소송의 기간과 효력","head":["주제","내용"],"rows":[["제소기간과 심리 범위","행정심판을 거치지 않으면 부작위가 계속되는 한 제소기간 제한이 없고 거쳤다면 재결서 정본을 송달받은 날부터 90일 안에 제기한다 · 위법판단 기준시는 사실심 변론종결시이다 · 심리는 부작위의 위법 여부에 그치고 작위의무의 이행이나 특정 처분의무까지 구할 수 없다"],["판결의 효력","판결이 확정되면 행정청은 이전 신청에 대해 처분할 의무를 지지만 신청대로 할 필요는 없어 거부처분을 해도 의무를 이행한 것이다"],["준용","기속력, 제3자효, 제3자 재심, 간접강제, 재판관할, 직권심리, 재량처분 취소, 관련청구 이송·병합은 준용된다(제38조 제2항) · 집행정지, 처분변경으로 인한 소의 변경, 사정판결은 준용되지 않는다"]]}],"10":[{"t":"def","term":"당사자소송","text":"처분등을 원인으로 하는 법률관계나 그 밖의 공법상 법률관계에 관한 소송으로 법률관계의 한쪽 당사자를 피고로 한다(제3조 제2호) · 대상이 처분이 아니라 공법상 법률관계라는 점에서 항고소송과, 공법관계라는 점에서 민사소송과 구별된다 · 확인판결뿐 아니라 이행판결도 할 수 있다"},{"t":"table","title":"당사자소송","head":["주제","내용"],"rows":[["피고와 원고","당사자소송의 피고는 행정청이 아니라 국가·공공단체 그 밖의 권리주체이다(제39조) · 부가가치세 환급청구나 납세의무부존재확인은 세무서장이 아니라 국가가 피고이고 세무서장을 피고로 했으면 피고경정을 허가할 수 있다 · 공무수탁사인이나 사인도 피고가 될 수 있고 원고적격 규정은 따로 없다"],["당사자소송인 사례","부가가치세 환급세액 지급청구, 명예퇴직 법관의 미지급 수당 청구, 지방소방공무원의 초과근무수당 청구, 공무원 지위 확인, 시립무용단원 해촉·시립합창단원 재위촉 거부·공중보건의사 채용계약 해지, 보조금 교부조건에 따른 반환청구, 국가의 조세채권존재확인 · 인가·고시 전 재건축·재개발조합 총회결의의 효력을 다투는 소송 · 행정소송규칙 제19조는 이런 유형과 공법상 계약에 따른 이행청구를 열거한다"],["당사자소송이 아닌 사례","인가·고시 후의 관리처분계획은 항고소송으로 다투고 조합과 조합장 사이 선임·해임 관계와 조합임원 선임결의 무효확인, 환매권 존부 확인은 민사소송이다 · 민주화운동관련자 보상심의위원회의 지급 기각결정, 산업단지관리공단의 입주계약 취소, 국유재산 변상금 부과는 처분이어서 항고소송으로 다툰다 · 취소사유에 그치는 하자 있는 처분의 효력은 공정력 때문에 당사자소송에서 부정할 수 없다"],["형식적 당사자소송","토지수용재결에 대한 보상금증감청구소송은 토지소유자가 사업시행자를 피고로 제기한다 · 수용재결 취소소송·이의재결 취소소송은 토지수용위원회가 피고이다 · 두 소송은 관련청구소송이어서 병합할 수 있다"]]},{"t":"table","title":"당사자소송의 준용","head":["주제","내용"],"rows":[["준용 규정","피고경정, 공동소송, 제3자·행정청 소송참가, 처분변경으로 인한 소의 변경, 기록 제출명령, 직권심리, 기속력(제30조 제1항), 소송비용 규정이 준용되고(제44조) 관할은 관계행정청 소재지를 피고 소재지로 본다(제40조)"],["준용되지 않는 규정","제소기간, 집행정지, 제3자효, 제3자 재심, 간접강제는 준용되지 않고 대신 민사집행법상 가처분이 준용된다 · 법령에 제소기간이 있으면 불변기간이고(제41조) 항고소송으로 소 변경이 가능하다(제42조)"],["가집행선고 제한 삭제","국가 상대 당사자소송에서 가집행선고를 금지하던 제43조는 헌법재판소 위헌결정(2020헌가12)으로 효력을 잃었고 2026.5.12 삭제되었다 · 지금은 국가를 상대로 한 당사자소송에서도 가집행선고를 할 수 있다 · 확인소송 형태의 당사자소송에는 민사소송과 같은 확인의 이익이 필요하다"]]},{"t":"tree","title":"객관소송","root":"객관소송","branches":[["민중소송","국가 또는 공공단체의 기관이 법률에 위반되는 행위를 한 때 자기의 법률상 이익과 관계없이 그 시정을 구하는 소송(제3조 제3호) · 법률이 정한 경우에 법률에 정한 자만 제기한다(제45조) · 공직선거법상 선거소송(선관위원장 피고, 대법원·고등법원 관할), 국민투표무효소송, 지방자치법상 주민소송이 해당한다"],["기관소송","국가 또는 공공단체의 기관 상호간 권한의 존부·행사에 관한 다툼에 대한 소송이고 헌법재판소 관장사항인 권한쟁의(지방자치단체 상호간 다툼 등)는 빠진다 · 지방의회 재의결에 대해 단체장이나 교육감이 대법원에 내는 소송이 대표 예이다"],["준용","민중·기관소송 중 취소를 구하면 취소소송, 무효·부작위 확인을 구하면 그 소송, 나머지는 당사자소송 규정을 성질에 반하지 않는 한 준용한다(제46조)"]]}]};
